SELECT 
    t.id, t.publisher_id, t.title, t.description,
    t.reward_amount, t.deposit_amount, t.deposit_status,
    t.category_id, c.name AS category_name,
    t.deadline, t.max_acceptors, t.current_acceptors,
    t.status, t.review_status, t.created_at, t.updated_at
FROM task t
LEFT JOIN task_category c ON t.category_id = c.id
WHERE t.deleted = 0

    AND t.publisher_id = #{query.publisherId}


    AND t.status = #{query.status}


    AND t.review_status = #{query.reviewStatus}


    AND t.category_id = #{query.categoryId}


    AND (t.title LIKE CONCAT('%', #{query.keyword}, '%') 
         OR t.description LIKE CONCAT('%', #{query.keyword}, '%'))


    AND t.reward_amount >= #{query.minReward}


    AND t.reward_amount <= #{query.maxReward}


    AND t.created_at >= #{query.startDate}


    AND t.created_at < #{query.endDate}

ORDER BY t.created_at DESC
LIMIT #{offset}, #{limit}

SELECT COUNT(*)
FROM task t
WHERE t.deleted = 0

    AND t.publisher_id = #{query.publisherId}


    AND t.status = #{query.status}


    AND t.review_status = #{query.reviewStatus}


    AND t.category_id = #{query.categoryId}


    AND (t.title LIKE CONCAT('%', #{query.keyword}, '%') 
         OR t.description LIKE CONCAT('%', #{query.keyword}, '%'))


    AND t.reward_amount >= #{query.minReward}


    AND t.reward_amount <= #{query.maxReward}


    AND t.created_at >= #{query.startDate}


    AND t.created_at < #{query.endDate}

SELECT t.id, t.publisher_id, t.title, t.description, t.reward_amount, t.deposit_amount, t.deposit_status, t.category_id, c.name AS category_name, t.deadline, t.max_acceptors, t.current_acceptors, t.status, t.review_status, t.created_at, t.updated_at FROM task t LEFT JOIN task_category c ON t.category_id = c.id WHERE t.deleted = 0 AND t.status = 2
AND t.category_id = #{query.categoryId}
AND (t.title LIKE CONCAT('%', #{query.keyword}, '%') OR t.description LIKE CONCAT('%', #{query.keyword}, '%'))
AND t.reward_amount >= #{query.minReward}
AND t.reward_amount <= #{query.maxReward}
ORDER BY t.created_at DESC LIMIT #{offset}, #{limit}

SELECT COUNT(*)
FROM task t
WHERE t.deleted = 0 AND t.status = 2

    AND t.category_id = #{query.categoryId}


    AND (t.title LIKE CONCAT('%', #{query.keyword}, '%') 
         OR t.description LIKE CONCAT('%', #{query.keyword}, '%'))


    AND t.reward_amount >= #{query.minReward}


    AND t.reward_amount <= #{query.maxReward}

SELECT t.id, t.publisher_id, t.title, t.description, t.reward_amount, t.deposit_amount, t.deposit_status, t.category_id, c.name AS category_name, t.deadline, t.max_acceptors, t.current_acceptors, t.status, t.review_status, t.created_at, t.updated_at FROM task t LEFT JOIN task_category c ON t.category_id = c.id WHERE t.deleted = 0 AND t.review_status = 0
AND t.category_id = #{query.categoryId}
AND (t.title LIKE CONCAT('%', #{query.keyword}, '%') OR t.description LIKE CONCAT('%', #{query.keyword}, '%'))
ORDER BY t.created_at ASC LIMIT #{offset}, #{limit}

SELECT COUNT(*) FROM task t WHERE t.deleted = 0 AND t.review_status = 0
AND t.category_id = #{query.categoryId}
AND (t.title LIKE CONCAT('%', #{query.keyword}, '%') OR t.description LIKE CONCAT('%', #{query.keyword}, '%'))
